const emptyProfile={name:'',age:'',gender:'',state:'',district:'',occupation:'',income:'',mobile:'',language:'English',familySize:'',residence:'',category:''};
const demoProfile={name:'Priya Sharma',age:'32',gender:'Female',state:'Uttar Pradesh',district:'Ghaziabad',occupation:'Teacher',income:'',mobile:'',language:'English',familySize:'4',residence:'Urban',category:''};
const get=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
const safeSet=(key,value)=>{try{window.localStorage.setItem(key,value)}catch{}};
const safeRemove=key=>{try{window.localStorage.removeItem(key)}catch{}};
const storageAvailable=(()=>{try{return Boolean(window.localStorage)}catch{return false}})();
const states=['Andhra Pradesh','Assam','Bihar','Delhi','Gujarat','Haryana','Karnataka','Kerala','Madhya Pradesh','Maharashtra','Punjab','Rajasthan','Tamil Nadu','Telangana','Uttar Pradesh','West Bengal','Other'];
const nav=[['/dashboard','Dashboard',LayoutDashboard],['/schemes','Government Schemes',ShieldCheck],['/assistant','AI Assistant',MessageCircle],['/hospitals','Hospital Finder',MapPin],['/scanner','Medical Report Scanner',ScanLine],['/profile','My Profile',UserRound]];
function Brand({light=false}){return <div className={'brand '+(light?'brand-light':'')}><span className="brand-icon"><HeartPulse size={21}/></span><span><strong>sahaara<span className="brand-dot">.</span></strong><small>HEALTH, TOGETHER</small></span></div>}
function eligibility(s,p){if(s.match)return s.match;let age=p.age!==''&&p.age!=null?Number(p.age):null;if(s.id==='pmjay'&&age!==null&&age>=70&&age<=120)return {status:'Potentially Eligible',reason:'The profile age is 70 or above. Indian citizenship, Aadhaar age and enrolment must be verified by the authority.',sourceUrl:'https://nha.gov.in/img/resources/English_FAQs_related_to_the_benefits_for_senior_citizens.pdf'};if(s.id==='rbsk'&&age!==null&&age>18&&age<=120)return {status:'Does Not Appear to Match',reason:'The profile holder is over 18. A child in the family may still be relevant.',sourceUrl:s.url};return {status:'More Information Required',reason:'The available profile does not establish entitlement or local access. Please check with the official scheme authority.',sourceUrl:s.url}}
function Status({s,p}){let e=eligibility(s,p).status;return <span className={'status '+(e==='Potentially Eligible'?'good':e==='Does Not Appear to Match'?'negative':'neutral')}><span className="status-dot"/>{e}</span>}
function Field({label,name,value,onChange,options,type='text',placeholder,hint,required=false,disabled=false}){return <label className="field"><span>{label}{required&&<b className="required"> *</b>}</span>{options?<select value={value??''} onChange={e=>onChange(name,e.target.value)} required={required}><option value="">Select {label.toLowerCase()}</option>{options.map(o=><option key={o}>{o}</option>)}</select>:<input type={type} value={value??''} placeholder={placeholder} onChange={e=>onChange(name,e.target.value)} required={required} disabled={disabled}/>} {hint&&<small>{hint}</small>}</label>}
function ProfileFields({p,set,registration=false,lockMobile=false}){const change=(n,v)=>set({...p,[n]:v});return <div className="fields-grid"><Field label="Full name" name="name" value={p.name} onChange={change} placeholder="Enter your full name" required/><Field label="Age" name="age" value={p.age} onChange={change} type="number" placeholder="Your age" required/><Field label="Gender (optional)" name="gender" value={p.gender} onChange={change} options={['Female','Male','Other','Prefer not to say']}/><Field label="State" name="state" value={p.state} onChange={change} options={states} required/><Field label="District" name="district" value={p.district} onChange={change} placeholder="Your district"/><Field label="Occupation" name="occupation" value={p.occupation} onChange={change} placeholder="Your occupation"/><Field label="Annual family income (₹)" name="income" value={p.income} onChange={change} type="number" placeholder="Optional"/><Field label="Mobile number" name="mobile" value={p.mobile} onChange={change} type="tel" placeholder="10-digit mobile number" required={registration} disabled={lockMobile} hint={lockMobile?"Mobile number cannot be changed here.":undefined}/><Field label="Preferred language" name="language" value={p.language} onChange={change} options={['English','Hindi','Bengali','Tamil','Telugu','Marathi','Other']}/><Field label="Family size" name="familySize" value={p.familySize} onChange={change} type="number" placeholder="Number of family members"/><Field label="Residence" name="residence" value={p.residence} onChange={change} options={['Rural','Urban']}/><Field label="Beneficiary details" name="category" value={p.category} onChange={change} options={['Not sure','BPL household','SC','ST','Other']} hint="Optional; helps you remember relevant details."/></div>}
function validateProfile(p){if(!p.name.trim()||p.age===''||p.age==null||!p.state)return 'Please enter your name, age and state.';if(!Number.isInteger(Number(p.age))||Number(p.age)<0||Number(p.age)>120)return 'Please enter a whole-number age between 0 and 120.';if(p.mobile&&!/^[6-9]\d{9}$/.test(p.mobile))return 'Please enter a valid 10-digit Indian mobile number.';if(p.income!==''&&p.income!=null&&(!Number.isSafeInteger(Number(p.income))||Number(p.income)<0||Number(p.income)>999999999))return 'Income must be a whole number between 0 and 999,999,999.';if(p.familySize!==''&&p.familySize!=null&&(!Number.isInteger(Number(p.familySize))||Number(p.familySize)<1||Number(p.familySize)>100))return 'Family size must be a whole number from 1 to 100.';return ''}
function Auth({onEnter,initialError=''}){const [mode,setMode]=useState('login'),[p,setP]=useState(emptyProfile),[mobile,setMobile]=useState(''),[password,setPassword]=useState(''),[error,setError]=useState(initialError),[busy,setBusy]=useState(false);async function submit(e){e.preventDefault();if(!storageAvailable){setError('Account sign-in is unavailable in this embedded preview. Open the website in a new tab.');return}if(mode==='register'){const err=validateProfile(p);if(err){setError(err);return}if(!/^[6-9]\d{9}$/.test(p.mobile)){setError('Please enter a valid 10-digit Indian mobile number.');return}if(password.length<12||new TextEncoder().encode(password).length>72){setError('Use a password of at least 12 characters and no more than 72 UTF-8 bytes.');return}}else if(!/^[6-9]\d{9}$/.test(mobile)||!password){setError('Enter your mobile number and password.');return}setError('');setBusy(true);try{const result=mode==='register'?await authApi.register({mobile:p.mobile,password,profile:profilePayload(p)}):await authApi.login({mobile,password});setPassword('');onEnter(result.user,'account',result.dataMode==='mock')}catch(err){setError(err.message)}finally{setBusy(false)}}return <div className="auth-shell"><div className="auth-left"><Brand light/><div className="auth-copy"><div className="eyebrow light-eye"><span/> A LITTLE CARE GOES A LONG WAY</div><h1>Healthcare feels<br/><em>better together.</em></h1><p>Understand your options, find the right care, and take the next step with confidence.</p><div className="auth-perks"><div><span><ShieldCheck size={20}/></span><div><b>Find support meant for you</b><small>Explore government healthcare schemes</small></div></div><div><span><HeartPulse size={20}/></span><div><b>Care, made more accessible</b><small>Helpful information, all in one place</small></div></div></div></div><div className="auth-bottom"><span>BUILT FOR EVERY INDIAN</span><span>Care starts here <Heart size={14}/></span></div><div className="auth-decor decor-one"/><div className="auth-decor decor-two"/></div><div className="auth-right"><div className="auth-mobile-brand"><Brand/></div><div className={'auth-form-wrap '+(mode==='register'?'wide':'')}><div className="auth-topline">YOUR HEALTH COMPANION <span>✳</span></div><h2>{mode==='login'?'Welcome to Sahaara':'Let’s get to know you'}</h2><p>{mode==='login'?'A little support for a healthier everyday.':'Tell us a little about yourself to personalize your experience.'}</p><div className="tabs"><button type="button" disabled={busy} className={mode==='login'?'active':''} onClick={()=>{setMode('login');setError('');setPassword('')}}>Log in</button><button type="button" disabled={busy} className={mode==='register'?'active':''} onClick={()=>{setMode('register');setError('');setPassword('')}}>Create an account</button></div><form onSubmit={submit}>{mode==='login'?<><Field label="Mobile number" name="mobile" value={mobile} onChange={(n,v)=>setMobile(v)} type="tel" placeholder="Enter your 10-digit mobile number" required/><div className="auth-password"><Field label="Password" name="password" value={password} onChange={(n,v)=>setPassword(v)} type="password" placeholder="Enter your password" required/></div></>:<><div className="form-section-title">PERSONAL INFORMATION <span>Fields marked * are required</span></div><ProfileFields p={p} set={setP} registration/><div className="auth-password"><Field label="Password" name="password" value={password} onChange={(n,v)=>setPassword(v)} type="password" placeholder="Create a password" required hint="At least 12 characters; maximum 72 UTF-8 bytes."/></div></>}<div className="demo-note"><Info size={16}/><span>Phone numbers are not verified by OTP. Some services use demonstration data.</span></div>{error&&<div className="form-error" role="alert"><AlertCircle size={16}/>{error}</div>}<button className="btn primary full" type="submit" disabled={busy}>{busy?'Please wait…':mode==='login'?'Continue to dashboard':'Create account'} <ArrowRight size={17}/></button></form>{mode==='login'&&<><div className="or"><span/>OR<span/></div><button className="btn outline full" disabled={busy} onClick={()=>onEnter(demoProfile,'demo')}>Explore with a demo profile <ArrowRight size={17}/></button></>}<p className="privacy-note"><ShieldCheck size={15}/> {storageAvailable?'Account details are sent to the configured server. Demo profiles stay in this browser.':'This embedded preview blocks browser storage. Demo changes will last only until you reload; open the website in a new tab for account features.'} Do not use real medical information in this prototype.</p></div><div className="auth-footer">MADE WITH CARE, FOR YOU <span>© SAHAARA HEALTH</span></div></div></div>}
function Sidebar({path,go,profile,logout,open,setOpen,isDemo}){return <><div className={'sidebar-overlay '+(open?'show':'')} onClick={()=>setOpen(false)}/><aside className={'sidebar '+(open?'open':'')}><div className="sidebar-brand"><Brand/><button className="icon-btn mobile-close" onClick={()=>setOpen(false)} aria-label="Close menu"><X size={19}/></button></div><div className="nav-label">YOUR SPACE</div><nav>{nav.map(([url,label,Icon])=><button key={url} className={'nav-item '+(path===url?'selected':'')} onClick={()=>{go(url);setOpen(false)}}><Icon size={18}/><span>{label}</span>{path===url&&<span className="nav-dot"/>}</button>)}</nav><div className="sidebar-bottom"><div className="side-help"><div className="side-help-icon"><Heart size={17}/></div><b>Here for your health.</b><p>Small steps make a big difference.</p></div><button className="nav-item logout" onClick={logout}><LogOut size={18}/> <span>Log out</span></button><div className="side-user"><div className="avatar">{profile.name?.[0]?.toUpperCase()||'U'}</div><div><b>{profile.name}</b><small>{isDemo?"Demo profile":"Personal account"}</small></div><ChevronDown size={15}/></div></div></aside></>}
function Header({title,profile,go,setOpen,isDemo,isMock}){return <header className="topbar"><button className="icon-btn menu-btn" onClick={()=>setOpen(true)} aria-label="Open menu"><Menu/></button><div className="mobile-header-brand"><Brand/></div><div className="breadcrumb"><span>YOUR HEALTH SPACE</span><ChevronRight size={14}/><b>{title}</b></div><div className="top-right"><span className="demo-pill"><span/> {isDemo?'DEMO MODE':isMock?'MOCK DATA':'ACCOUNT'}</span><button className="header-profile" onClick={()=>go('/profile')}><span className="avatar small">{profile.name?.[0]?.toUpperCase()||'U'}</span><span>{profile.name?.split(' ')[0]}</span><ChevronDown size={15}/></button></div></header>}
function PageHeading({eyebrow,title,desc,action}){return <div className="page-heading"><div>{eyebrow&&<div className="eyebrow"><span/> {eyebrow}</div>}<h1>{title}</h1><p>{desc}</p></div>{action}</div>}
function SchemeCard({s,p,saved,toggle,open,compact=false}){return <article className={'scheme-card '+(compact?'compact':'')}><div className="scheme-top"><div className={'scheme-icon '+s.color}><ShieldCheck size={21}/></div><button className={'bookmark '+(saved?'is-saved':'')} onClick={(e)=>{e.stopPropagation();toggle(s.id)}} aria-label={saved?'Unsave scheme':'Save scheme'}>{saved?<BookmarkCheck size={19}/>:<Bookmark size={19}/>}</button></div><div className="scheme-tag">{s.tag} <span>•</span> {s.scope==='state'?'STATE GOVERNMENT':'CENTRAL GOVERNMENT'}</div><button className="text-title" onClick={()=>open(s)}>{s.name}</button><p>{s.description}</p>{!compact&&<div className="scheme-meta"><div><b>MAIN BENEFIT</b><span>{s.benefit}</span></div><div><b>FOR WHOM</b><span>{s.target}</span></div><div><b>DOCUMENTS</b><span>{s.documents}</span></div></div>}<div className="scheme-card-foot"><Status s={s} p={p}/><button className="link-arrow" onClick={()=>open(s)} aria-label={'View '+s.name}><ArrowUpRight size={18}/></button></div></article>}
function Dashboard({p,go,saved,toggle,open,recent,schemes,catalogLoading,catalogError,isDemo}){let cards=[{title:'Government Schemes',desc:'Find healthcare schemes that may be right for you and your family.',icon:ShieldCheck,color:'mint',action:'Explore schemes',to:'/schemes',num:'01'},{title:'AI Healthcare Assistant',desc:'Get simple guidance and answers to your health questions.',icon:MessageCircle,color:'blue',action:'Ask a question',to:'/assistant',num:'02'},{title:'Hospital Finder',desc:'Discover healthcare facilities and explore care near you.',icon:MapPin,color:'peach',action:'Find a hospital',to:'/hospitals',num:'03'},{title:'Medical Report Scanner',desc:'Keep your reports organized and understand the details.',icon:FileHeart,color:'lavender',action:'Scan a report',to:'/scanner',num:'04'}];let completion=Math.round(['name','age','state','district','occupation','language','familySize','residence'].filter(k=>p[k]!==''&&p[k]!=null).length/8*100);return <><div className="dashboard-welcome"><div><div className="eyebrow"><span/> YOUR HEALTH, YOUR WAY</div><h1>Good to see you, {p.name?.split(' ')[0]} <span className="wave">✳</span></h1><p>Your healthcare assistance, all in one place.</p></div><div className="profile-summary"><div className="summary-icon"><UserRound size={19}/></div><div><b>Your profile</b><span>{p.age!==''&&p.age!=null?`${p.age} years`:'Age not set'} <i>•</i> {p.state||'State not set'} <i>•</i> {p.language||'English'}</span></div><button onClick={()=>go('/profile')} aria-label="Edit profile"><ArrowUpRight size={17}/></button></div></div><section className="hero"><div className="hero-content"><div className="hero-tag"><Sparkles size={14}/> A LITTLE SUPPORT FOR EVERY STEP</div><h2>Care that starts<br/><em>with understanding.</em></h2><p>From finding the right scheme to finding the right care, we're here to make your health journey a little easier.</p><button className="btn hero-btn" onClick={()=>go('/schemes')}>Explore your options <ArrowRight size={17}/></button></div><div className="hero-art" aria-hidden="true"><div className="art-ring ring-a"/><div className="art-ring ring-b"/><div className="art-cross cross-one">✳</div><div className="art-cross cross-two">✦</div><div className="art-heart"><HeartPulse size={57} strokeWidth={1.3}/></div><div className="art-card art-card-one"><span><Check size={14}/></span><div><b>Care, made simple</b><small>Here whenever you need</small></div></div><div className="art-card art-card-two"><Heart size={17} fill="currentColor"/><span>Made for you</span></div></div></section><div className="section-heading"><div><div className="eyebrow"><span/> HOW CAN WE HELP?</div><h2>Everything you need, in one place.</h2><p>Choose where you’d like to begin today.</p></div><span className="section-index">01 / YOUR SERVICES</span></div><div className="service-grid">{cards.map(c=><article className="service-card" key={c.title}><div className="service-card-top"><div className={'service-icon '+c.color}><c.icon size={22}/></div><span>{c.num}</span></div><h3>{c.title}</h3><p>{c.desc}</p><button onClick={()=>go(c.to)}>{c.action} <ArrowRight size={16}/></button></article>)}</div><div className="dashboard-lower"><div><div className="section-heading lower-heading"><div><div className="eyebrow"><span/> DISCOVER SUPPORT</div><h2>Healthcare schemes for you</h2><p>A good place to start exploring available support.</p></div><button className="text-link" onClick={()=>go('/schemes')}>View all schemes <ArrowRight size={15}/></button></div>{catalogLoading&&<p className="tiny-disclaimer">Loading schemes…</p>}{catalogError&&<p className="form-error" role="alert">{catalogError}</p>}{!catalogLoading&&!catalogError&&!schemes.length&&<p className="tiny-disclaimer">No schemes available. Ask an administrator to load the scheme database.</p>}<div className="scheme-grid dashboard-schemes">{schemes.slice(0,2).map(s=><SchemeCard key={s.id} s={s} p={p} saved={saved.includes(s.id)} toggle={toggle} open={open} compact/>)}</div><p className="tiny-disclaimer"><Info size={14}/> {isDemo?'Demo match':'Preliminary match'} is not a guarantee. Verify on the official website.</p></div><aside className="completion-card"><div className="completion-head"><div className="service-icon mint"><UserRound size={21}/></div><ArrowUpRight size={17}/></div><h3>A little more about you</h3><p>A complete profile can help you explore more relevant schemes.</p><div className="progress-label"><b>Profile completion</b><strong>{completion}%</strong></div><div className="progress"><span style={{width:completion+'%'}}/></div><button className="btn outline full" onClick={()=>go('/profile')}>Complete your profile <ArrowRight size={16}/></button><div className="saved-mini"><Bookmark size={16}/><span>{saved.length} saved {saved.length===1?'scheme':'schemes'}</span><button onClick={()=>go('/profile')}>View</button></div></aside></div><div className="recent-strip"><Clock size={17}/><span><b>Recently viewed</b> {recent.length?recent.map(id=>schemes.find(s=>s.id===id)?.name).filter(Boolean).join(' · '):'Schemes you explore will appear here.'}</span></div></>}
function SchemesPage({p,saved,toggle,open,isDemo,schemes}){const [search,setSearch]=useState(''),[category,setCategory]=useState(''),[beneficiary,setBeneficiary]=useState(''),[state,setState]=useState(''),[results,setResults]=useState([]),[loading,setLoading]=useState(!isDemo),[error,setError]=useState('');useEffect(()=>{if(isDemo)return;const controller=new AbortController();setLoading(true);setError('');const timer=setTimeout(()=>{schemeApi.list({q:search.trim(),category,beneficiary,state},controller.signal).then(data=>setResults(data.schemes)).catch(err=>{if(err.name!=='AbortError')setError(err.message)}).finally(()=>{if(!controller.signal.aborted)setLoading(false)})},250);return()=>{clearTimeout(timer);controller.abort()}},[isDemo,search,category,beneficiary,state,p.age]);let filtered=isDemo?schemes.filter(s=>(s.name+' '+s.description+' '+s.benefit+' '+s.target).toLowerCase().includes(search.trim().toLowerCase())&&(!category||s.category===category)&&(!beneficiary||s.beneficiary===beneficiary)):results;return <><PageHeading eyebrow="SUPPORT FOR YOU" title="Government Healthcare Schemes" desc={isDemo?'Explore sample scheme information in demo mode.':'Explore sourced healthcare initiatives and find a place to start.'}/><div className="notice"><Info size={18}/><span><b>A helpful starting point, not a guarantee.</b> Matching is preliminary and considers the profile holder, not other family members. Confirm details, state implementation and eligibility with the official scheme authority.</span></div><div className="filterbar"><div className="searchbox"><Search size={18}/><input placeholder="Search schemes, benefits or keywords" maxLength={100} value={search} onChange={e=>setSearch(e.target.value)}/></div><select aria-label="Filter by state" value={state} onChange={e=>setState(e.target.value)}><option value="">All states</option>{states.map(s=><option key={s}>{s}</option>)}</select><select aria-label="Filter by category" value={category} onChange={e=>setCategory(e.target.value)}><option value="">All categories</option>{['Health cover','Maternal health','Child health'].map(s=><option key={s}>{s}</option>)}</select><select aria-label="Filter by beneficiary" value={beneficiary} onChange={e=>setBeneficiary(e.target.value)}><option value="">All beneficiaries</option>{['Families','Pregnant women','Children'].map(s=><option key={s}>{s}</option>)}</select></div>{state&&<p className="filter-hint">Central schemes are included for {state}, but their local implementation is not verified.</p>}<div className="result-head"><div><h2>Explore schemes</h2><p>{loading?'Loading schemes…':`${filtered.length} ${filtered.length===1?'scheme':'schemes'} to explore`}</p></div><span className="section-index">GOVERNMENT INITIATIVES</span></div>{error?<div className="form-error" role="alert">{error}</div>:loading?null:filtered.length?<div className="scheme-grid">{filtered.map(s=><SchemeCard key={s.id} s={s} p={p} saved={saved.includes(s.id)} toggle={toggle} open={open}/>)}</div>:<div className="empty"><Search size={24}/><h3>No schemes found</h3><p>Try a different search or filter. If the database is new, it may need to be seeded.</p></div>}<p className="tiny-disclaimer"><Info size={14}/> Scheme information is summarized from official sources. Requirements can change; check the linked source.</p></>}
function SchemeModal({s,p,saved,toggle,close,error}){if(!s)return null;return <div className="modal-bg" onClick={close}><div className="modal" role="dialog" aria-modal="true" onClick={e=>e.stopPropagation()}><div className="modal-top"><span className={'scheme-icon '+s.color}><ShieldCheck size={22}/></span><button className="icon-btn" onClick={close} aria-label="Close"><X/></button></div><div className="scheme-tag">{s.tag} · {s.scope==='state'?'STATE GOVERNMENT':'CENTRAL GOVERNMENT'}</div><h2>{s.name}</h2><Status s={s} p={p}/><p className="modal-disclaimer">{eligibility(s,p).reason} This is not an official determination.</p><div className="detail-sections">{[['About the scheme',s.description],['Benefits offered',s.benefit],['Eligibility criteria',s.criteria],['Required documents',s.documents],['How to apply',s.apply]].map(([a,b])=><div key={a}><h3>{a}</h3><p>{b}</p></div>)}</div><p className="source">Source: {s.source}{s.sourceReviewedAt&&<> · Reviewed {new Date(s.sourceReviewedAt).toLocaleDateString('en-IN')}</>}</p>{officialUrl(eligibility(s,p).sourceUrl)&&<a className="text-link" href={officialUrl(eligibility(s,p).sourceUrl)} target="_blank" rel="noreferrer">View matching source <ExternalLink size={14}/></a>}{error&&<div className="form-error" role="alert">{error}</div>}<div className="modal-actions">{officialUrl(s.url)?<a className="btn primary" href={officialUrl(s.url)} target="_blank" rel="noreferrer">Visit official website <ExternalLink size={16}/></a>:<span className="source-warning">Official link unavailable; verify independently.</span>}<button className="btn outline" onClick={()=>toggle(s.id)}>{saved?<BookmarkCheck size={16}/>:<Bookmark size={16}/>} {saved?'Saved scheme':'Save scheme'}</button></div></div></div>}
